.typost-ps-8,
.typost-styled.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8,
.typost-styled[data-style-id="8"][data-style-id][data-style-id][data-style-id][data-style-id] {
    font-weight: 700;
    word-spacing: 0.05em;
    text-wrap: pretty;
}

.typost-ps-8:not([style*="text-align"], [class*="has-text-align-"]),
.typost-styled.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8:not([style*="text-align"], [class*="has-text-align-"]),
.typost-styled[data-style-id="8"][data-style-id][data-style-id][data-style-id][data-style-id]:not([style*="text-align"], [class*="has-text-align-"]) {
    text-align: justify;
    text-align-last: center;
}

.typost-ps-8,
.typost-styled.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8,
.typost-styled[data-style-id="8"][data-style-id][data-style-id][data-style-id][data-style-id] {
    --typost-hang: 0.2;
}

.typost-ps-8:not([style*="text-align"], [class*="has-text-align-"]),
.typost-styled.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8.typost-ps-8:not([style*="text-align"], [class*="has-text-align-"]),
